@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=EB+Garamond:wght@400;500;600;700&display=swap');
:root{--ink:#191c19;--ink-soft:#252923;--gold:#c8a667;--gold-bright:#e1c487;--paper:#e9dfc9;--muted:#a19b8b;--board-light:#e4d4b5;--board-dark:#71644f;--board-light-hi:#f1d98f;--board-dark-hi:#b59b65;--serif:'EB Garamond',Georgia,serif;--display:'Cinzel',Georgia,serif}
*{box-sizing:border-box}html{min-height:100%;background:#151815}body{margin:0;min-height:100vh;color:var(--paper);font-family:var(--serif);background:radial-gradient(ellipse at 50% 38%,#25261f 0,#1b1e1b 48%,#151815 100%);background-attachment:fixed}.app-shell{max-width:1280px;margin:auto;padding:0 54px}.topbar{height:83px;display:flex;align-items:center;border-bottom:1px solid #ffffff12;position:relative}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{font-size:29px;color:var(--gold);line-height:1;text-shadow:0 0 24px #d5af6130}.brand-copy{display:grid;gap:3px}.brand-copy strong{font:600 12px var(--display);letter-spacing:1.75px;color:#e3d8c0}.brand-copy small{font:9px var(--display);letter-spacing:1.5px;color:#8f8a7b}.top-meta{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;font:9px var(--display);letter-spacing:1.2px;color:#aaa391}.live-dot,.history-dot{width:7px;height:7px;border-radius:50%;background:#93ad77;box-shadow:0 0 9px #8ea96775}.meta-divider{height:13px;width:1px;background:#ffffff25;margin:0 5px}.icon-button{margin-left:auto;background:none;border:1px solid #ffffff21;color:var(--gold);width:35px;height:35px;border-radius:50%;font-size:17px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--gold);background:#c8a66710}.game-layout{display:grid;grid-template-columns:minmax(0,690px) minmax(270px,330px);justify-content:center;gap:54px;padding:31px 0 29px}.matchline{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:20px}.eyebrow,.section-kicker{font:9px var(--display);letter-spacing:2px;color:var(--gold)}h1{font:500 32px var(--display);letter-spacing:.1px;margin:5px 0 0;color:#eae0cb}h1 em{font-family:var(--serif);font-size:38px;font-weight:400;color:var(--gold-bright)}.round-pill{border:1px solid #c8a66738;border-radius:20px;padding:7px 10px 6px;font:8px var(--display);letter-spacing:.8px;color:#c5b99d;margin-bottom:5px;display:flex;align-items:center;gap:7px}.pill-dot{width:5px;height:5px;background:var(--gold);border-radius:50%}.player-strip{height:57px;display:flex;align-items:center;gap:12px;padding:0 13px;background:linear-gradient(90deg,#ffffff09,transparent);border:1px solid #ffffff0d}.opponent-strip{border-radius:5px 5px 0 0;border-bottom:0}.your-strip{border-radius:0 0 5px 5px;border-top:0}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-size:23px}.avatar-dark{background:#393a32;color:#cbc1a7;border:1px solid #ffffff17}.avatar-light{background:#dbcaa7;color:#423a2b;border:1px solid #ecd7aa}.player-info{min-width:0}.player-name{font:9px var(--display);letter-spacing:1.15px;color:#e0d6c1;display:flex;align-items:center;gap:8px}.you-tag{font-size:7px;color:#cfba8b;border:1px solid #c8a66755;padding:2px 4px;letter-spacing:.7px}.you-tag-light{color:#d7c49c}.player-caption{font:12px var(--serif);color:#898575;margin-top:3px}.player-clock{margin-left:auto;font:20px var(--display);letter-spacing:.5px;color:#c4b89d;font-variant-numeric:tabular-nums}.active-clock{color:#e2c47f}.board-frame{position:relative;padding:11px;background:#3a342a;box-shadow:0 16px 40px #0005,0 0 0 1px #d5b87555,0 0 0 4px #171815,0 0 0 5px #c5a3636b}.chessboard{width:100%;aspect-ratio:1;display:grid;grid-template-columns:repeat(8,1fr);grid-template-rows:repeat(8,1fr);overflow:hidden;user-select:none;touch-action:manipulation}.square{position:relative;display:grid;place-items:center;border:0;padding:0;cursor:pointer;aspect-ratio:1;min-width:0;min-height:0}.square.light{background:var(--board-light)}.square.dark{background:var(--board-dark)}.square.last-move.light{background:var(--board-light-hi)}.square.last-move.dark{background:var(--board-dark-hi)}.square.selected.light{background:#f1d77d}.square.selected.dark{background:#b49b62}.square:focus-visible{outline:3px solid #f6db85;outline-offset:-3px;z-index:5}.square.in-check.light{background:#e5a078}.square.in-check.dark{background:#a75948}.piece{font-family:'DejaVu Sans',serif;font-size:clamp(28px,5.25vw,59px);line-height:1;position:relative;z-index:1;transition:transform .13s ease;filter:drop-shadow(0 2px 1px #0003)}.square:hover .piece{transform:translateY(-2px)}.piece.white{color:#fff7e7;text-shadow:0 1px 2px #53442e,0 0 1px #382c1e,-1px 0 #645238,1px 0 #645238}.piece.black{color:#302a22;text-shadow:0 1px 0 #c0ae8b,-1px 0 #c3ae86,1px 0 #c3ae86;filter:drop-shadow(0 2px 1px #0004)}.legal-dot{position:absolute;width:23%;height:23%;border-radius:50%;background:#403b2e4a;z-index:2;pointer-events:none}.square.dark .legal-dot{background:#eee0bf70}.legal-capture:after{content:'';position:absolute;inset:4px;border:4px solid #52442f72;border-radius:50%;z-index:2;pointer-events:none}.square.dark.legal-capture:after{border-color:#f1e2c075}.coord{position:absolute;font:9px var(--display);font-weight:600;z-index:3;pointer-events:none}.coord.file{right:4px;bottom:2px}.coord.rank{left:4px;top:2px}.light .coord{color:#736349}.dark .coord{color:#e2d3b2}.board-ornament{position:absolute;color:#d4b26e;font-size:10px;z-index:4;line-height:1}.ornament-tl{top:0;left:0;transform:translate(-45%,-45%)}.ornament-tr{top:0;right:0;transform:translate(45%,-45%)}.ornament-bl{bottom:0;left:0;transform:translate(-45%,45%)}.ornament-br{bottom:0;right:0;transform:translate(45%,45%)}.board-footer{height:43px;display:flex;align-items:center;justify-content:space-between;font:9px var(--display);letter-spacing:.8px;color:#948f80}.board-footer>span:first-child{display:flex;gap:7px;align-items:center}.board-footer kbd,.control-btn kbd{font:9px var(--display);border:1px solid #ffffff28;border-radius:3px;padding:2px 5px;color:#c8b890}.footer-center{display:flex;align-items:center;gap:7px;color:#c5b99d}.turn-indicator{width:6px;height:6px;border-radius:50%;background:#d2af69;box-shadow:0 0 8px #d2af6970}.text-button{background:none;border:0;padding:8px 0;color:#b8ad96;font:9px var(--display);letter-spacing:.7px;cursor:pointer}.text-button:hover{color:var(--gold-bright)}
@media(max-width:1060px){.app-shell{padding:0 30px}.game-layout{gap:30px;grid-template-columns:minmax(0,620px) minmax(250px,300px)}}
@media(max-width:820px){.app-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,620px);max-width:660px;margin:auto;gap:20px;padding-top:24px}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:12px}.turn-card{grid-column:span 2}.moves-panel{grid-row:span 2;min-height:245px}.moves-list{max-height:160px}.controls-panel{align-self:start}.motto{grid-column:span 2}.top-meta{position:static;transform:none;margin-left:auto;margin-right:15px}.topbar{height:70px}}
@media(max-width:520px){.app-shell{padding:0 13px}.topbar{height:61px}.brand-mark{font-size:25px}.brand-copy strong{font-size:10px;letter-spacing:1.2px}.brand-copy small{font-size:7px;letter-spacing:1px}.top-meta{font-size:7px;gap:6px;margin-right:8px}.icon-button{width:31px;height:31px}.game-layout{padding-top:18px;gap:16px}.matchline{margin-bottom:13px}h1{font-size:25px}h1 em{font-size:30px}.round-pill{font-size:7px;padding:6px 7px}.player-strip{height:50px;padding:0 9px;gap:9px}.avatar{width:30px;height:30px;font-size:20px}.player-name{font-size:7.7px;letter-spacing:.8px}.player-caption{font-size:11px}.player-clock{font-size:17px}.board-frame{padding:7px}.piece{font-size:clamp(29px,9vw,45px)}.coord{font-size:7px}.coord.file{right:3px;bottom:1px}.coord.rank{left:3px;top:1px}.board-footer{height:38px;font-size:7px;letter-spacing:.45px}.board-footer kbd{font-size:8px}.text-button{font-size:7px;letter-spacing:.35px}.side-panel{grid-template-columns:1fr;gap:10px}.turn-card,.motto{grid-column:auto}.moves-panel{grid-row:auto;min-height:230px}.moves-list{max-height:145px}.site-footer{font-size:7px!important;letter-spacing:.7px!important}.promotion-options{gap:7px!important}.promotion-choice{width:57px!important;height:63px!important;font-size:37px!important}}
@media(max-width:350px){.app-shell{padding:0 8px}.top-meta{display:none}.piece{font-size:27px}.board-frame{padding:5px}.player-name{font-size:7px}}

