const boardEl=document.getElementById('chessboard');
const glyph={K:'♔',Q:'♕',R:'♖',B:'♗',N:'♘',P:'♙',k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'};
const names={K:'King',Q:'Queen',R:'Rook',B:'Bishop',N:'Knight',P:'Pawn'};
const initialBoard=()=>['rnbqkbnr','pppppppp','........','........','........','........','PPPPPPPP','RNBQKBNR'].join('').split('').map(x=>x==='.'?null:x);
let game={board:initialBoard(),turn:'w',castle:{K:true,Q:true,k:true,q:true},ep:-1,half:0,full:1,history:[],moves:[],captured:{w:[],b:[]},last:null,selected:-1,legal:[],over:false,flipped:false};
let clock={w:600,b:600,running:true,last:Date.now()};
let soundOn=false,toastTimer;
const sideOf=p=>!p?null:(p===p.toUpperCase()?'w':'b');
const fileOf=i=>i%8, rankOf=i=>Math.floor(i/8), squareName=i=>'abcdefgh'[fileOf(i)]+(8-rankOf(i));
function clonePosition(){return{board:game.board.slice(),turn:game.turn,castle:{...game.castle},ep:game.ep,half:game.half,full:game.full}}
function attacked(pos,target,by){const b=pos.board,f=fileOf(target),r=rankOf(target);for(let i=0;i<64;i++){const p=b[i];if(!p||sideOf(p)!==by)continue;const x=fileOf(i),y=rankOf(i),df=f-x,dr=r-y,type=p.toLowerCase();if(type==='p'&&Math.abs(df)===1&&dr===(by==='w'?-1:1))return true;if(type==='n'&&((Math.abs(df)===1&&Math.abs(dr)===2)||(Math.abs(df)===2&&Math.abs(dr)===1)))return true;if(type==='k'&&Math.max(Math.abs(df),Math.abs(dr))===1)return true;let dirs=[];if(type==='r'||type==='q')dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(type==='b'||type==='q')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dx,dy]of dirs){let xx=x+dx,yy=y+dy;while(xx>=0&&xx<8&&yy>=0&&yy<8){const at=yy*8+xx;if(at===target)return true;if(b[at])break;xx+=dx;yy+=dy}}}return false}
function kingSquare(pos,side){return pos.board.findIndex(p=>p===(side==='w'?'K':'k'))}
function inCheck(pos,side){const k=kingSquare(pos,side);return k<0||attacked(pos,k,side==='w'?'b':'w')}
function pseudoMoves(pos,from){const b=pos.board,p=b[from],side=sideOf(p),type=p.toLowerCase(),f=fileOf(from),r=rankOf(from),out=[];if(type==='p'){const d=side==='w'?-1:1,start=side==='w'?6:1,last=side==='w'?0:7,one=(r+d)*8+f;if(r+d>=0&&r+d<8&&!b[one]){out.push({from,to:one,promotion:rankOf(one)===last});const two=(r+2*d)*8+f;if(r===start&&!b[two])out.push({from,to:two})}for(const df of[-1,1]){const x=f+df,y=r+d;if(x<0||x>7||y<0||y>7)continue;const to=y*8+x;if((b[to]&&sideOf(b[to])!==side)||(to===pos.ep))out.push({from,to,ep:to===pos.ep,promotion:y===last})}return out}
const add=(x,y)=>{if(x<0||x>7||y<0||y>7)return false;const to=y*8+x;if(!b[to]){out.push({from,to});return true}if(sideOf(b[to])!==side)out.push({from,to});return false};if(type==='n'){for(const[df,dr]of[[1,2],[2,1],[-1,2],[-2,1],[1,-2],[2,-1],[-1,-2],[-2,-1]])add(f+df,r+dr);return out}if(type==='k'){for(let df=-1;df<=1;df++)for(let dr=-1;dr<=1;dr++)if(df||dr)add(f+df,r+dr);const row=side==='w'?7:0,king=side==='w'?'K':'k',enemy=side==='w'?'b':'w';if(from===row*8+4&&!inCheck(pos,side)){for(const[short,right,rookFile,clear]of[[true,side==='w'?'K':'k',7,[5,6]],[false,side==='w'?'Q':'q',0,[1,2,3]]]){if(pos.castle[right]&&b[row*8+rookFile]===(side==='w'?'R':'r')&&clear.every(x=>!b[row*8+x])){const transit=row*8+(short?5:3),dest=row*8+(short?6:2);if(!attacked(pos,transit,enemy)&&!attacked(pos,dest,enemy))out.push({from,to:dest,castle:short?'king':'queen'})}}}return out}const dirs=[];if(type==='r'||type==='q')dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(type==='b'||type==='q')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[df,dr]of dirs){let x=f+df,y=r+dr;while(x>=0&&x<8&&y>=0&&y<8){if(!add(x,y))break;x+=df;y+=dr}}return out}
function applyCore(pos,m,promote='q'){const b=pos.board,p=b[m.from],side=sideOf(p),target=b[m.to];if(target){if(target==='R')pos.castle.Q=false;if(target==='R'&&m.to===63)pos.castle.K=false;if(target==='r'&&m.to===0)pos.castle.q=false;if(target==='r'&&m.to===7)pos.castle.k=false}b[m.from]=null;if(m.ep)b[m.to+(side==='w'?8:-8)]=null;if(m.castle){const row=side==='w'?7:0,rookFrom=row*8+(m.castle==='king'?7:0),rookTo=row*8+(m.castle==='king'?5:3);b[rookTo]=b[rookFrom];b[rookFrom]=null}b[m.to]=m.promotion?(side==='w'?promote.toUpperCase():promote):p;if(p==='K'){pos.castle.K=false;pos.castle.Q=false}if(p==='k'){pos.castle.k=false;pos.castle.q=false}if(p==='R'&&m.from===56)pos.castle.Q=false;if(p==='R'&&m.from===63)pos.castle.K=false;if(p==='r'&&m.from===0)pos.castle.q=false;if(p==='r'&&m.from===7)pos.castle.k=false;pos.ep=p.toLowerCase()==='p'&&Math.abs(m.to-m.from)===16?(m.to+m.from)/2:-1;pos.half=p.toLowerCase()==='p'||target||m.ep?0:pos.half+1;if(side==='b')pos.full++;pos.turn=side==='w'?'b':'w';return target||null}
function legalMoves(pos,from){const p=pos.board[from];if(!p)return[];const side=sideOf(p);return pseudoMoves(pos,from).filter(m=>{const test={...pos,board:pos.board.slice(),castle:{...pos.castle}};applyCore(test,m);return !inCheck(test,side)})}
function allLegal(pos,side){let moves=[];for(let i=0;i<64;i++)if(sideOf(pos.board[i])===side)moves.push(...legalMoves(pos,i));return moves}

